function icon(name, size, color){
  size=size||24; color=color||'#333';
  var body='';
  if(name==='circle') body='<circle cx="12" cy="12" r="10" fill="'+color+'"/>';
  else if(name==='square') body='<rect x="3" y="3" width="18" height="18" rx="2" fill="'+color+'"/>';
  else if(name==='triangle') body='<polygon points="12,3 22,21 2,21" fill="'+color+'"/>';
  else if(name==='star') body='<polygon points="12,2 15,9 22,9 16,14 18,21 12,17 6,21 8,14 2,9 9,9" fill="'+color+'"/>';
  else if(name==='heart') body='<path d="M12 21l-7-7c-4-4 1-9 4-6l3 3 3-3c3-3 8 2 4 6z" fill="'+color+'"/>';
  else body='<rect x="3" y="3" width="18" height="18" rx="2" fill="'+color+'"/>';
  return '<svg xmlns="http://www.w3.org/2000/svg" width="'+size+'" height="'+size+'" viewBox="0 0 24 24">'+body+'</svg>';
}
var EXPORTS={icon:icon};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.SvgIconForgePure = EXPORTS; }
